#!/usr/bin/env node
/**
 * Regenerate scripts/lib/core.mjs from a checkout of the Clane platform monorepo.
 *
 *   node scripts/vendor/build.mjs --monorepo <path-to-monorepo>
 *
 * core.mjs bundles the exact parsers, tree digest and signature code the Clane server
 * runs (registry/remote/layout + tarball, registry/digest, cli/canonical + signing and the
 * data-provider manifest schemas), so this repo's CI cannot disagree with the server.
 * It stands in for the @clane/registry-schema package, which is not published yet.
 * zod and js-yaml stay external and come from this repo's package.json.
 *
 * esbuild is taken from the monorepo's own node_modules; nothing is installed here.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { resolve, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const args = process.argv.slice(2);
const at = args.indexOf('--monorepo');
if (at === -1 || !args[at + 1]) {
  console.error('usage: node scripts/vendor/build.mjs --monorepo <path>');
  process.exit(2);
}
const mono = resolve(args[at + 1]);
const here = fileURLToPath(new URL('.', import.meta.url));
const outfile = resolve(here, '..', 'lib', 'core.mjs');
const posix = (p) => p.replace(/\\/g, '/');
const src = (rel) => posix(join(mono, rel));

const requireFromMono = createRequire(join(mono, 'package.json'));
const { build } = await import(pathToFileURL(requireFromMono.resolve('esbuild')).href);
const commit = execFileSync('git', ['-C', mono, 'rev-parse', 'HEAD']).toString().trim();
const dirty = execFileSync('git', [
  '-C', mono, 'status', '--porcelain', '--',
  'packages/api/src/registry', 'packages/api/src/cli', 'packages/data-provider/src/types',
]).toString().trim();
if (dirty) {
  console.error(`refusing to vendor uncommitted sources:\n${dirty}`);
  process.exit(1);
}

const api = 'packages/api/src';
const types = 'packages/data-provider/src/types';
const entry = [
  `export { buildCatalogue, itemFiles, KIND_DIRS, SKILL_FILE, WORKFLOW_FILE, REPO_MANIFEST_FILE } from '${src(`${api}/registry/remote/layout.ts`)}';`,
  `export { extractTarGz } from '${src(`${api}/registry/remote/tarball.ts`)}';`,
  `export { computeArtefactSha256 } from '${src(`${api}/registry/digest.ts`)}';`,
  `export { canonicalise } from '${src(`${api}/cli/canonical.ts`)}';`,
  `export { signDocument, verifyDocument, deriveKid } from '${src(`${api}/cli/signing.ts`)}';`,
  `export { parseSkill } from '${src(`${api}/registry/skills/parser.ts`)}';`,
  `export { registrySlugSchema } from '${src(`${types}/registry.ts`)}';`,
].join('\n');
const dataProvider = ['skills', 'atlasRoles', 'atlasWorkflows', 'registry']
  .map((name) => `export * from '${src(`${types}/${name}.ts`)}';`)
  .join('\n');

const shims = {
  name: 'clane-shims',
  setup(b) {
    b.onResolve({ filter: /^librechat-data-provider$/ }, () => ({ path: 'dp', namespace: 'shim' }));
    b.onResolve({ filter: /\/roles\/store$/ }, () => ({ path: 'role-store', namespace: 'shim' }));
    b.onLoad({ filter: /^dp$/, namespace: 'shim' }, () => ({ contents: dataProvider, loader: 'ts', resolveDir: mono }));
    b.onLoad({ filter: /^role-store$/, namespace: 'shim' }, () => ({
      contents: "export const ROLE_MANIFEST_FILE = 'role.yaml';",
      loader: 'ts',
    }));
  },
};

const banner = [
  '/**',
  ` * GENERATED by scripts/vendor/build.mjs from the Clane platform monorepo @ ${commit}.`,
  ' * Do not edit by hand: regenerate instead (see docs/contributing.md).',
  ' * Stand-in for the unpublished @clane/registry-schema package: the same parsers, tree',
  ' * digest and Ed25519 signing code the Clane server runs.',
  ' */',
].join('\n');

const result = await build({
  stdin: { contents: entry, resolveDir: mono, loader: 'ts', sourcefile: 'core-entry.ts' },
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node20',
  external: ['zod', 'js-yaml'],
  plugins: [shims],
  legalComments: 'none',
  logLevel: 'error',
  banner: { js: banner },
  write: false,
});
writeFileSync(outfile, result.outputFiles[0].text);
console.log(`wrote ${outfile} from ${commit}`);
